	template<bool isJoin>
	static void wrapper(Instance* instance)
	{
		PartInstance* part = dynamic_cast<PartInstance*>(instance);
		if (part)
		{
			if (isJoin)
				part->join();
			else
				part->destroyJoints();
		}
		else
		{
			instance->for_eachChild(&wrapper<isJoin>);
		}
	}

